import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const p=JSON.parse('{"title":"Configuration Reference","description":"Every Blue Mod Installer setting — admin options, search parameters, and the conf.yml manifest.","frontmatter":{"title":"Configuration Reference","description":"Every Blue Mod Installer setting — admin options, search parameters, and the conf.yml manifest."},"headers":[],"relativePath":"blue-mod-installer/configuration/reference.md","filePath":"blue-mod-installer/configuration/reference.md","lastUpdated":1785522590000}'),a={name:"blue-mod-installer/configuration/reference.md"};function c(n,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><h2 id="admin-settings" tabindex="-1">Admin settings <a class="header-anchor" href="#admin-settings" aria-label="Permalink to &quot;Admin settings&quot;">​</a></h2><p>Managed at <strong>Admin → Extensions → Blue Mod Installer</strong> (<code>/admin/extensions/bluemodinstaller</code>). Values are stored by Blueprint&#39;s extension settings store and take effect immediately (the extension caches them under the <code>bluemodinstaller_settings</code> cache key, which is flushed on save).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>string (max 255)</td><td><em>(empty)</em></td><td>Your CurseForge API key, sent as <code>X-API-Key</code> on every CurseForge request. <strong>Server-side only</strong> — users never see it. Leave empty to disable CurseForge (Modrinth still works). Get a key at <a href="https://console.curseforge.com/" target="_blank" rel="noreferrer">https://console.curseforge.com/</a>.</td></tr><tr><td><code>default_provider</code></td><td><code>modrinth</code> | <code>curseforge</code></td><td><code>modrinth</code></td><td>Provider pre-selected when a user opens the Mod Installer tab.</td></tr><tr><td><code>default_page_size</code></td><td><code>6</code> | <code>12</code> | <code>24</code> | <code>48</code></td><td><code>6</code></td><td>Results per page in the search grid.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">CurseForge keys</p><p>Rotating the key is safe — save the form and the next search uses the new key. A missing or invalid key surfaces as a provider error in the UI, not a panel error.</p></div><h2 id="search-parameters" tabindex="-1">Search parameters <a class="header-anchor" href="#search-parameters" aria-label="Permalink to &quot;Search parameters&quot;">​</a></h2><p>These are the query parameters accepted by the search endpoint (used by the UI; documented for custom API clients — see <a href="./../user-guide/api">API Reference</a>):</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>provider</code></td><td><code>modrinth</code> | <code>curseforge</code></td><td><code>modrinth</code></td><td>Which provider to query.</td></tr><tr><td><code>page</code></td><td>int ≥ 1</td><td><code>1</code></td><td>Page number.</td></tr><tr><td><code>page_size</code></td><td>int</td><td><code>6</code></td><td>Results per page.</td></tr><tr><td><code>search_query</code></td><td>string</td><td><em>(empty)</em></td><td>Free-text search.</td></tr><tr><td><code>loader</code></td><td>string</td><td><em>(empty)</em></td><td>Loader filter (e.g. <code>fabric</code>, <code>forge</code>, <code>quilt</code>, <code>neoforge</code>). Empty = all loaders.</td></tr><tr><td><code>sort_by</code></td><td>string</td><td>provider default</td><td>Modrinth: <code>relevance</code>, <code>downloads</code>, <code>follows</code>, <code>newest</code>, <code>updated</code> (fallback <code>downloads</code>). CurseForge: numeric sort field (fallback <code>6</code> = total downloads).</td></tr><tr><td><code>minecraft_version</code></td><td>string</td><td><em>(empty)</em></td><td>MC version filter, e.g. <code>1.20.1</code>. Empty = all versions.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Behavior since 1.12.4</p><p>Omitting <code>sort_by</code> or <code>loader</code> previously produced a <code>500</code> (the empty values were forwarded to the provider verbatim). Since 1.12.4 the backend applies the defaults above and skips empty facets.</p></div><h2 id="extension-manifest-conf-yml" tabindex="-1">Extension manifest (<code>conf.yml</code>) <a class="header-anchor" href="#extension-manifest-conf-yml" aria-label="Permalink to &quot;Extension manifest (`conf.yml`)&quot;">​</a></h2><p>Located at <code>blueprint/bluemodinstaller/conf.yml</code> in the repo. You normally never edit these — Blueprint reads them at install time.</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.identifier</code></td><td><code>bluemodinstaller</code></td><td>Extension identifier — used in all paths and URLs.</td></tr><tr><td><code>info.version</code></td><td><code>1.12.4</code></td><td>Extension version (shown on the admin page).</td></tr><tr><td><code>info.target</code></td><td><code>beta-2026-06</code></td><td>Blueprint version the extension targets.</td></tr><tr><td><code>info.compatibility</code></td><td><code>beta-2026-01/02/05/06</code></td><td>Blueprint versions accepted at install time.</td></tr><tr><td><code>admin.view</code> / <code>admin.controller</code></td><td><code>view.blade.php</code> / <code>controller.php</code></td><td>The admin settings page.</td></tr><tr><td><code>dashboard.components</code></td><td><code>components</code></td><td>React components mounted by Blueprint&#39;s build.</td></tr><tr><td><code>requests.app</code></td><td><code>controllers</code></td><td>Client API controllers.</td></tr><tr><td><code>requests.routers.client</code></td><td><code>routes.php</code></td><td>Client API router, mounted at <code>/api/client/extensions/bluemodinstaller</code>.</td></tr></tbody></table>',12)])])}const u=t(a,[["render",c]]);export{p as __pageData,u as default};
